import { randomUUID,createHash } from 'node:crypto';
import type pg from 'pg';
import { requireWebBaby,WebAccessError } from '@growdesk/database';
import { mediaProviderConfig,transcribeMedia,generateMediaJson,MediaProviderError,type MediaKind } from '@growdesk/adapters';
import type { TaskProcessor,TaskExecutionContext } from './worker-engine.js';
import { createPrivateMediaReader,type PrivateMedia,type ReadPrivateMedia } from './private-media.js';
interface MediaJob {id:string;user_id:string;family_id:string;baby_id:string;kind:MediaKind;input:{attachmentId?:string;targetDate?:string}}
export interface MediaProcessorOptions {env?:NodeJS.ProcessEnv;readMedia?:ReadPrivateMedia}
function validatedResult(kind:MediaKind,result:Record<string,unknown>):Record<string,unknown> {
  const invalid=()=>{throw new MediaProviderError('AI_PROVIDER_INVALID_RESPONSE','Structured result failed validation',502);};
  if(kind==='growth_ocr') {
    for(const [key,max] of [['weightKg',200],['heightCm',250],['headCircumferenceCm',100]] as const) {
      const value=result[key];if(value!=null&&(typeof value!=='number'||!Number.isFinite(value)||value<=0||value>max)) invalid();
    }
    if(['weightKg','heightCm','headCircumferenceCm'].every(k=>result[k]==null)) invalid();
    if(result.date!=null&&(typeof result.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(result.date)||(!Number.isFinite(Date.parse(result.date))||new Date(result.date).toISOString().slice(0,10)!==result.date))) invalid();
    return {date:result.date??null,weightKg:result.weightKg??null,heightCm:result.heightCm??null,headCircumferenceCm:result.headCircumferenceCm??null};
  }
  if(kind==='medical_ocr') {
    if(typeof result.title!=='string'||!Array.isArray(result.items)||result.items.length>500) invalid();
    const items=(result.items as unknown[]).map((value,index)=>{
      if(!value||typeof value!=='object'||Array.isArray(value)) return invalid();
      const item=value as Record<string,unknown>;
      if(typeof item.name!=='string'||(typeof item.value!=='string'&&typeof item.value!=='number')) return invalid();
      for(const k of ['unit','referenceRange']) if(item[k]!=null&&typeof item[k]!=='string') invalid();
      return {id:`item_${index}`,name:item.name,value:String(item.value),unit:item.unit??'',referenceRange:item.referenceRange??'',status:['normal','high','low','abnormal'].includes(String(item.flag))?item.flag:'unknown',interpretation:''};
    });
    return {title:result.title,category:'general',date:typeof result.date==='string'?result.date:null,hospital:typeof result.hospital==='string'?result.hospital:null,items,aiSummary:'仅为原单据转录草稿。空白参考区间或未知标记表示未识别到印刷内容，不代表正常。请核对原件；医学解读需由医生完成。'};
  }
  if(typeof result.headline!=='string'||!result.sections||typeof result.sections!=='object'||Array.isArray(result.sections)) invalid();
  const sections=result.sections as Record<string,unknown>;
  for(const key of ['feeding','sleep','diaper','growthAndCare','tomorrowTips']) if(typeof sections[key]!=='string') invalid();
  return {headline:result.headline,sections,highlights:Array.isArray(result.highlights)?result.highlights.filter(x=>typeof x==='string').slice(0,6):[],
    suggestedQuestions:Array.isArray(result.suggestedQuestions)?result.suggestedQuestions.filter(x=>typeof x==='string').slice(0,5):[],
    disclaimer:'仅根据已记录的数据生成，不构成诊断或治疗建议。缺失记录不代表未发生。',isAiGenerated:true,generatedAt:new Date().toISOString()};
}
async function summaryFacts(pool:pg.Pool,job:MediaJob,timezone:string) {
  const targetDate=job.input.targetDate;
  if(!targetDate) throw new WebAccessError(400,'INVALID_JOB_INPUT','Summary date is missing');
  const bounds=await pool.query<{start:Date;end:Date}>(`SELECT ($1::date::timestamp AT TIME ZONE $2) AS start, (($1::date+1)::timestamp AT TIME ZONE $2) AS end`,[targetDate,timezone]);
  const {start,end}=bounds.rows[0]!;
  const lists:Record<string,unknown>={date:targetDate,timeZone:timezone};
  for(const [kind,table,filter] of [
    ['feeding','feeding_records','occurred_at >= $2 AND occurred_at < $3'],
    ['diaper','diaper_records','occurred_at >= $2 AND occurred_at < $3'],
    ['sleep','sleep_records','started_at < $3 AND (ended_at IS NULL OR ended_at > $2)'],
    ['supplement','supplement_records','occurred_at >= $2 AND occurred_at < $3'],
  ]) {
    const rows=await pool.query(`SELECT * FROM ${table} WHERE baby_id=$1 AND deleted_at IS NULL AND ${filter} LIMIT 1001`,[job.baby_id,start,end]);
    if(rows.rows.length>1000) throw new WebAccessError(413,'SUMMARY_TOO_LARGE','Daily records exceed the summary input limit; no partial summary was generated');
    lists[kind!]=rows.rows.map(r=>{const {family_id:_family,recorded_by_user_id:_user,...rest}=r as Record<string,unknown>;return rest;});
  }
  const foods=await pool.query('SELECT record_date,food_item_ids,portion_description,reaction,notes FROM food_records WHERE baby_id=$1 AND record_date=$2 AND deleted_at IS NULL LIMIT 1001',[job.baby_id,targetDate]);
  if(foods.rows.length>1000) throw new WebAccessError(413,'SUMMARY_TOO_LARGE','Daily food records exceed the input limit');
  lists.food=foods.rows;
  const growth=await pool.query('SELECT measurement_date,weight_kg,height_cm,head_circumference_cm,notes FROM growth_measurements WHERE baby_id=$1 AND measurement_date=$2 AND deleted_at IS NULL LIMIT 1001',[job.baby_id,targetDate]);
  const medical=await pool.query('SELECT report_date,title,hospital,department,diagnosis,notes,items FROM medical_reports WHERE baby_id=$1 AND report_date=$2::date AND deleted_at IS NULL LIMIT 1001',[job.baby_id,targetDate]);
  if(growth.rows.length>1000||medical.rows.length>1000) throw new WebAccessError(413,'SUMMARY_TOO_LARGE','Daily growth or medical records exceed the input limit');
  lists.growth=growth.rows;lists.medical=medical.rows;return lists;
}
export function createMediaProcessor(kind:MediaKind,pool:pg.Pool,options:MediaProcessorOptions={}):TaskProcessor {
  const env=options.env??process.env;
  const read=options.readMedia??createPrivateMediaReader(env);
  return {kind,async execute(ctx:TaskExecutionContext){
    // Input comes only from an authoritative job row, not queue payload or client identity hints.
    const rows=await pool.query<MediaJob>('SELECT * FROM web_background_jobs WHERE id=$1 AND kind=$2',[ctx.taskId,kind]);
    const job=rows.rows[0];
    if(!job||ctx.ownerScope!==`user:${job.user_id}`) throw new WebAccessError(404,'JOB_NOT_FOUND','Authorized job input is absent');
    const baby=await requireWebBaby(pool,job.user_id,job.baby_id);
    const config=mediaProviderConfig(kind,env);
    let result:Record<string,unknown>;let attachment:PrivateMedia|undefined;
    if(kind==='daily_summary_synthesis') {
      const facts=await summaryFacts(pool,job,baby.timezone);
      const raw=await generateMediaJson(`用中文根据以下有时区的完整当日记录总结。不要把缺失数据说成异常或未发生，不打健康分。返回 headline、highlights、suggestedQuestions 和 sections(含 feeding,sleep,diaper,growthAndCare,tomorrowTips 字符串)。\n${JSON.stringify(facts)}`,config,undefined,ctx.signal);
      result={...validatedResult(kind,raw),date:job.input.targetDate,babyId:job.baby_id,babyName:baby.nickname};
    } else {
      const media=await pool.query<PrivateMedia>(`SELECT id,object_key,mime_type,byte_size,sha256 FROM attachments WHERE id=$1 AND family_id=$2 AND baby_id=$3 AND uploader_id=$4 AND status='ready' AND deleted_at IS NULL`,[job.input.attachmentId,job.family_id,job.baby_id,job.user_id]);
      attachment=media.rows[0];if(!attachment) throw new WebAccessError(404,'ATTACHMENT_NOT_FOUND','Private attachment is no longer available');
      const bytes=await read(attachment,ctx.signal);
      // Apply integrity limits also to custom storage implementations.
      if(bytes.byteLength!==attachment.byte_size||createHash('sha256').update(bytes).digest('hex')!==attachment.sha256.trim()) throw new WebAccessError(502,'MEDIA_HASH_MISMATCH','Attachment bytes failed integrity verification');
      if(kind==='voice_transcription') result={text:await transcribeMedia(bytes,attachment.mime_type,config,ctx.signal),attachmentId:attachment.id};
      else {
        const prompt=kind==='growth_ocr'?'提取图片中实际可见的测量日期 YYYY-MM-DD、体重公斤 weightKg、身长厘米 heightCm、头围厘米 headCircumferenceCm。未知值为 null，不推测。返回 JSON。':'提取医疗单据实际可见的 title、date、hospital、items 数组(每项 name,value,unit,referenceRange,flag)。缺失参考范围保留空白，不推导诊断或年龄参考值。未知 flag 为 unknown。返回 JSON 草稿。';
        const raw=await generateMediaJson(prompt,config,{bytes,mimeType:attachment.mime_type},ctx.signal);
        result={...validatedResult(kind,raw),attachmentId:attachment.id,imageUrl:`/api/attachments/${attachment.id}`};
      }
    }
    if(ctx.isCancelled()) throw new WebAccessError(409,'TASK_CANCELLED','Task was cancelled');
    return {result,publish:async(db:pg.PoolClient)=>{
      await requireWebBaby(db,job.user_id,job.baby_id,true,kind==='daily_summary_synthesis');
      if(attachment) {
        const accessible=await db.query(`SELECT id FROM attachments WHERE id=$1 AND family_id=$2 AND baby_id=$3 AND uploader_id=$4 AND status='ready' AND deleted_at IS NULL AND sha256=$5 FOR SHARE`,[attachment.id,job.family_id,job.baby_id,job.user_id,attachment.sha256]);
        if(!accessible.rowCount) throw new WebAccessError(404,'ATTACHMENT_NOT_FOUND','Attachment revoked before result publication');
      }
      if(kind==='daily_summary_synthesis') await db.query(`INSERT INTO daily_summaries(id,baby_id,family_id,target_date,content,version,created_at,updated_at)
        VALUES($1,$2,$3,$4::date,$5,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
        ON CONFLICT(baby_id,target_date) DO UPDATE SET content=EXCLUDED.content,version=daily_summaries.version+1,updated_at=CURRENT_TIMESTAMP`,[randomUUID(),job.baby_id,job.family_id,job.input.targetDate,JSON.stringify(result)]);
      await db.query(`INSERT INTO notifications(id,user_id,event_key,title,body,data,created_at) VALUES($1,$2,$3,$4,$5,$6::jsonb,CURRENT_TIMESTAMP) ON CONFLICT(id) DO NOTHING`,[job.id,job.user_id,`web_job:${job.id}`,'处理已完成','结果已保存，可打开查看并确认。',JSON.stringify({type:'ai',jobId:job.id,babyId:job.baby_id})]);
    }};
  }};
}
